void metric_sample_projector::collect_values(const std::string &prefix,
                                             const json &value,
                                             std::map<std::string, double> &out,
                                             std::set<std::string> &interval_paths) {
	if(is_stat_object(value)) {
		out[prefix] = first_stat_value(value);
		if(value.contains("window") && value.at("window").is_number()) interval_paths.insert(prefix);
		return;
	}
	if(value.is_number()) {
		out[prefix] = value.get<double>();
		return;
	}
	if(!value.is_object() || value.is_array()) return;
	for(auto it = value.begin(); it != value.end(); ++it) {
		const auto child_prefix = prefix.empty() ? it.key() : prefix + "." + it.key();
		collect_values(child_prefix, it.value(), out, interval_paths);
	}
}

void metric_sample_projector::set_path(json &out, const std::string &path, json value) {
	json *cursor = &out;
	std::size_t start = 0;
	while(true) {
		const std::size_t dot = path.find('.', start);
		const auto part = path.substr(start, dot == std::string::npos ? std::string::npos : dot - start);
		if(dot == std::string::npos) {
			(*cursor)[part] = std::move(value);
			return;
		}
		if(!cursor->contains(part) || !(*cursor)[part].is_object()) (*cursor)[part] = json::object();
		cursor = &(*cursor)[part];
		start = dot + 1;
	}
}

